// Main component structure
class AboutScreen {
  constructor(triggerEl, options = {}) {
    this.triggerEl = triggerEl;
    this.modal = null;
    this.isOpen = false;
    this.options = {
      modalContainer: document.body,
      appVersion: '1.0.0',
      features: [],
      onClose: null,
      ...options
    };
    this.init();
  }

  init() {
    this.bindEvents();
    this.checkHash();
  }

  bindEvents() {
    this.triggerEl.addEventListener('click', () => this.open());
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.isOpen) this.close();
    });
  }

  async open() {
    if (this.isOpen) return;
    this.isOpen = true;
    this.modal = this.createModal();
    this.options.modalContainer.appendChild(this.modal);
    this.animateOpen();
    this.emit('aboutOpen');
  }

  close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.animateClose(() => {
      this.modal.remove();
      this.modal = null;
      this.emit('aboutClose');
      if (this.options.onClose) this.options.onClose();
    });
  }
}
```

