## 2. WebGL Fragment Shader Implementation
```glsl
// Uniforms: channelMode (0=Red,1=Green,2=Blue,3=Hue), thresholdValue, tolerance, invert
precision highp float;
uniform sampler2D u_image;
uniform vec2 u_textureSize;
uniform int u_channelMode;
uniform float u_threshold;
uniform float u_tolerance;
uniform bool u_invert;

vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

void main() {
    vec2 uv = gl_FragCoord.xy / u_textureSize;
    vec4 color = texture2D(u_image, uv);
    float channelValue;

    if (u_channelMode == 0) { // Red channel
        channelValue = color.r;
    } else if (u_channelMode == 1) { // Green channel
        channelValue = color.g;
    } else if (u_channelMode == 2) { // Blue channel
        channelValue = color.b;
    } else { // Hue-based (for blue/cyan targeting)
        vec3 hsv = rgb2hsv(color.rgb);
        // Map blue/cyan hue range (180-240 degrees) to 0-1
        channelValue = mod((hsv.x * 360.0 - 180.0) / 60.0, 1.0);
    }

    float thresholded = step(u_threshold, channelValue);
    if (u_channelMode == 3) {
        // Apply tolerance for hue-based selection
        thresholded = 1.0 - smoothstep(0.0, u_tolerance, abs(channelValue - 0.5));
    }

    if (u_invert) thresholded = 1.0 - thresholded;

    gl_FragColor = vec4(vec3(thresholded), color.a);
}
```

