```javascript
// GDPR compliance note: This is strictly necessary UI state, not tracking
const STORAGE_KEY = 'monochromifier_about_seen';
const ABOUT_SELECTOR = '#about-box';

let aboutElement = null;
let isVisible = false;

export function initAboutScreen() {
  aboutElement = document.querySelector(ABOUT_SELECTOR);
  if (!aboutElement) {
    console.error('About screen element not found');
    return;
  }

  // Check first-visit state
  const hasSeen = localStorage.getItem(STORAGE_KEY);
  if (!hasSeen) {
    showAboutScreen();
  }

  // Setup event listeners
  setupEventListeners();
}

export function showAboutScreen() {
  if (!aboutElement) return;

  // Close conflicting modals first
  closeConflictingModals();

  aboutElement.classList.add('visible');
  aboutElement.setAttribute('aria-hidden', 'false');
  isVisible = true;

  // Mark as seen immediately to prevent re-showing on reload
  markAsSeen();

  // Trap focus for accessibility
  trapFocus(aboutElement);
}

export function hideAboutScreen() {
  if (!aboutElement) return;

  aboutElement.classList.remove('visible');
  aboutElement.setAttribute('aria-hidden', 'true');
  isVisible = false;

  // Release focus trap
  releaseFocusTrap();
}

export function toggleAboutScreen() {
  isVisible ? hideAboutScreen() : showAboutScreen();
}

export function markAsSeen() {
  // Store timestamp for potential future use
  localStorage.setItem(STORAGE_KEY, Date.now().toString());
}

export function shouldShowOnFirstVisit() {
  return !localStorage.getItem(STORAGE_KEY);
}

function setupEventListeners() {
  // Close button
  const closeBtn = aboutElement.querySelector('.modal-close');
  closeBtn?.addEventListener('click', hideAboutScreen);

  // ESC key (handled globally in input.js, but backup here)
  aboutElement.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      hideAboutScreen();
    }
  });

  // Click outside to close
  aboutElement.addEventListener('click', (e) => {
    if (e.target === aboutElement) {
      hideAboutScreen();
    }
  });
}

function closeConflictingModals() {
  // Close help screen if open
  if (window.helpScreen && window.helpScreen.isVisible?.()) {
    window.helpScreen.hide();
  }
}

// Focus trap implementation for accessibility
let previousFocus = null;
function trapFocus(element) {
  previousFocus = document.activeElement;
  const focusable = element.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
  if (focusable.length > 0) {
    focusable[0].focus();
  }
}

function releaseFocusTrap() {
  previousFocus?.focus();
}

// Export state for external coordination
export function isAboutScreenVisible() {
  return isVisible;
}
```

