Create `src/modal-manager.js`:

```javascript
const MODAL_ZINDEX = {
  about: 1000,
  help: 1001  // Help should appear above About if both triggered
};

const openModals = new Set();

export function registerModal(name, element, getVisibleFn) {
  openModals.add({ name, element, getVisibleFn });
}

export function showModal(modalName) {
  // Close all modals except the target one
  for (const modal of openModals) {
    if (modal.name !== modalName && modal.getVisibleFn()) {
      closeModal(modal.name);
    }
  }

  // Show target modal
  const target = Array.from(openModals).find(m => m.name === modalName);
  if (target) {
    target.element.style.zIndex = MODAL_ZINDEX[modalName];
    target.element.classList.add('visible');
  }
}

export function closeModal(modalName) {
  const modal = Array.from(openModals).find(m => m.name === modalName);
  if (modal) {
    modal.element.classList.remove('visible');
  }
}

export function getTopmostModal() {
  return Array.from(openModals)
    .filter(m => m.getVisibleFn())
    .sort((a, b) => (b.element.style.zIndex || 0) - (a.element.style.zIndex || 0))[0];
}
```

