Pseudo-code structure:
```javascript
function createModal(config) {
  const modal = {
    id: config.id,
    storageKey: config.storageKey,
    conflictsWith: config.conflictsWith || [],

    show() {
      // Close conflicting modals first
      this.conflictsWith.forEach(conflict => conflict.hide());
      // Show logic with event bleed-through protection
      document.getElementById(this.id).classList.add('visible');
      // localStorage persistence if storageKey provided
      if (this.storageKey) localStorage.setItem(this.storageKey, 'visible');
      if (config.onShow) config.onShow();
    },

    hide() {
      document.getElementById(this.id).classList.remove('visible');
      if (this.storageKey) localStorage.setItem(this.storageKey, 'hidden');
      if (config.onHide) config.onHide();
    },

    toggle() {
      this.isVisible() ? this.hide() : this.show();
    },

    isVisible() {
      return document.getElementById(this.id).classList.contains('visible');
    }
  };

  // Setup ESC key handler and draggability if enabled
  return modal;
}

// Re-instantiate help screen
