## Code Example Structure
```javascript
// text-sources.js
export const createTumblrSource = (apiKey) => ({
  id: 'tumblr',
  name: 'Poetical Bot',
  isNetworkSource: true,
  async fetchText() {
    const response = await fetch(`https://api.tumblr.com/v2/blog/poeticalbot/posts?api_key=${apiKey}&limit=1&offset=${Math.floor(Math.random() * 100)}`);
    const data = await response.json();
    return data.response.posts[0].summary.split(/\s+/).filter(w => w.length > 0);
  }
});

// sketch.js
let lastBundledSource = textSources.find(s => !s.isNetworkSource);

async function loadFromSource() {
  p.noLoop();
  statusBlade.value = 'Loading...';
  try {
    const newWords = await selectedSource.fetchText();
    reinitializeWords(newWords);
    if (!selectedSource.isNetworkSource) lastBundledSource = selectedSource;
    statusBlade.value = 'Loaded successfully';
  } catch (error) {
    statusBlade.value = `Error: ${error.message}, using ${lastBundledSource.name}`;
    const fallbackWords = await lastBundledSource.fetchText();
    reinitializeWords(fallbackWords);
  } finally {
    p.loop();
    setTimeout(() => statusBlade.value = '', 3000);
  }
}
```
